<?php
require_once __DIR__.'/business-production.php';$recipes=query('SELECT * FROM biz_recipes WHERE active=1 ORDER BY id')->fetchAll(PDO::FETCH_UNIQUE);$edit=(int)($_GET['recipe']??0);$r=$recipes[$edit]??null;
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='biz_recipe_save') {
 $edit=(int)($_POST['id']??0);$r=['name'=>pv('name'),'base_g'=>pv('base_g','1000'),'base_unit'=>pv('base_unit','g'),'ingredients'=>'[]'];$lines=[];foreach($_POST['material']??[] as $i=>$m)$lines[]=['material'=>is_string($m)?$m:'','basis'=>$_POST['basis'][$i]??'product','mode'=>$_POST['mode'][$i]??'percent','amount'=>$_POST['amount'][$i]??0,'unit'=>$_POST['unit'][$i]??'g'];
} else $lines=$r?json_decode($r['ingredients'],true):[];
$materials=['배추','무우','절임소금','총각무','열무','갓','파'];foreach($recipes as $rec)foreach(json_decode($rec['ingredients'],true) as $line)$materials[]=$line['material'];$materials=array_unique($materials);
function recipeOptions(array $recipes,int $selected): void {echo '<option value="0">배합 기준 미등록</option>';foreach($recipes as $id=>$r)echo '<option value="'.(int)$id.'" '.($id===$selected?'selected':'').'>'.e($r['name']).'</option>';}
?>
<div class="toolbar"><a class="button secondary" href="/?page=biz-production">← 생산 계획</a><a class="button" href="/?page=biz-production-settings#recipe-editor">＋ 배합 기준 추가</a></div>
<section class="panel"><h2>배합 기준 목록</h2><p class="hint">무게 기준은 제품 무게당 % 또는 재료량을 입력합니다. 수량 기준은 1개당 g·개·컵·줄을 입력합니다. 배추·무우의 합이 100%를 넘어도 원재료 손실을 포함한 기준으로 사용할 수 있습니다.</p>
<div class="table-wrap"><table><thead><tr><th>배합</th><th>기준 제품량</th><th>재료별 기준</th><th>관리</th></tr></thead><tbody><?php foreach($recipes as $id=>$rec): ?><tr><td><?=e($rec['name'])?></td><td><?=(int)$rec['base_g']?> <?=e($rec['base_unit'])?></td><td><?php foreach(json_decode($rec['ingredients'],true) as $line): ?><small><?=e($line['material'])?>: <?=e(rtrim(rtrim(number_format((float)$line['amount'],4,'.',''),'0'),'.'))?> <?=$line['mode']==='grams'?e($line['unit']??'g').' / 기준 제품량': '% × '.e($line['basis']==='product'?'제품무게':$line['basis'].'무게')?></small><?php endforeach ?></td><td><a class="button secondary" href="/?page=biz-production-settings&recipe=<?=(int)$id?>#recipe-editor">수정</a><form method="post"><?=csrf()?><input type="hidden" name="action" value="biz_recipe_delete"><input type="hidden" name="id" value="<?=(int)$id?>"><button class="text-button" data-confirm="이 배합 기준을 삭제할까요? 연결 제품은 기준 확인 필요로 표시되고 저장된 계획은 유지됩니다.">삭제</button></form></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel minor-action" id="recipe-editor"><h2><?=$edit?'배합 기준 수정':'새 배합 기준'?></h2><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="biz_recipe_save"><input type="hidden" name="id" value="<?=$edit?>"><div class="form-grid"><label>배합 이름<input name="name" value="<?=e($r['name']??'')?>" maxlength="100" required></label><label>기준 제품량<input name="base_g" type="number" min="1" max="1000000" value="<?=e((string)($r['base_g']??1000))?>" required></label><label>기준 단위<select name="base_unit"><option value="g" <?=($r['base_unit']??'g')==='g'?'selected':''?>>g (무게 기준)</option><option value="개" <?=($r['base_unit']??'g')==='개'?'selected':''?>>개 (수량 기준)</option></select></label></div>
<p class="hint">예: 배추 95%, 기준은 제품무게. 절임소금 9.5%, 기준은 배추. g 입력은 위 기준 제품량에 필요한 재료 무게입니다. 재료 행을 비우거나 행 삭제 버튼을 누르면 제외됩니다.</p>
<div id="ingredient-lines"><?php for($i=0;$i<max(4,count($lines)+1);$i++): $line=$lines[$i]??['material'=>'','basis'=>'product','mode'=>'percent','amount'=>'','unit'=>'g']; ?><div class="ingredient-row"><label>재료명<input name="material[]" list="material-names" maxlength="40" value="<?=e($line['material'])?>"></label><label>양<input name="amount[]" type="number" step="0.0001" min="0" max="1000000" value="<?=e(rtrim(rtrim(number_format((float)$line['amount'],4,'.',''),'0'),'.'))?>"></label><label>단위<select name="mode[]"><option value="percent" <?=$line['mode']==='percent'?'selected':''?>>%</option><option value="grams" <?=$line['mode']==='grams'?'selected':''?>>기준량당 양</option></select></label><label>재료 단위<select name="unit[]"><?php foreach(['g','개','컵','줄'] as $u): ?><option value="<?=$u?>" <?=($line['unit']??'g')===$u?'selected':''?>><?=$u?></option><?php endforeach ?></select></label><label>비율 기준<input name="basis[]" list="basis-names" value="<?=e($line['basis']==='product'?'제품무게':$line['basis'])?>" maxlength="40"></label><button type="button" class="button secondary" data-remove-ingredient>행 삭제</button></div><?php endfor ?></div>
<datalist id="material-names"><?php foreach($materials as $m): ?><option value="<?=e($m)?>"></option><?php endforeach ?></datalist><datalist id="basis-names"><option value="제품무게"></option><?php foreach($materials as $m): ?><option value="<?=e($m)?>"></option><?php endforeach ?></datalist><p class="hint">비율 기준에서 제품무게 또는 재료명(예: 배추)을 선택하세요. 다른 재료명(예: 배추)을 입력하면 그 재료의 계산된 무게가 기준입니다.</p><div class="actions"><button type="button" class="button secondary" id="add-ingredient">＋ 재료 행 추가</button><button class="button">배합 기준 저장</button></div></form></section>
<section class="panel"><h2>판매상품별 배합 연결</h2><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="biz_recipe_links"><?php foreach(query('SELECT p.*,l.recipe_id,l.weight_g FROM biz_products p LEFT JOIN biz_recipe_links l ON l.product_id=p.id WHERE p.active=1 ORDER BY p.id')->fetchAll() as $p): ?><div class="biz-recipe-link"><strong><?=e(bizKo($p))?></strong><label>배합<select name="recipe[<?=$p['id']?>]"><?php recipeOptions($recipes,(int)$p['recipe_id']); ?></select></label><label>제품 1개 무게(g)<input name="weight[<?=$p['id']?>]" type="number" min="0" max="1000000" value="<?=(int)$p['weight_g']?>"></label></div><?php endforeach ?><p class="hint">무게 기준 배합에는 제품 1개의 무게를 입력합니다. 개수 기준 배합은 무게가 없어도 계산합니다. 이 배합은 판매 관리 전용이며 김치방의 배합에는 영향을 주지 않습니다.</p><button class="button">배합 연결 저장</button></form></section>
